3113213X322
.112...2211
.1.31.21112
...........
...........
...........
...........
...........
...........
...........
...........",
];

fn main() {
    let mut sum = 0.0;
    for (i, level) in LEVELS.iter().enumerate() {
        let mut g = Game::new(level);
        let total = g.bricks_left() as f64;
        for _ in 0..2500 {
            if g.status() != "playing" {
